refentry.refsect1:
  &reftitle.examples;

   Exemplo de Yaf_Response_Abstract::__construct


<?php
/* normalmente não é necessário construir uma resposta manualmente:
 * o despachante cria um e o disponibiliza */
$response = Yaf_Dispatcher::getInstance()->getResponse();

/* construir diretamente é útil principalmente em testes */
$response = new Yaf_Response_Http();
$response->setBody("Hello World");

echo $response;
?>


   &example.outputs.similar;


Hello World
